-- Katalóg silových cvikov v DB (namiesto 5 miest v kóde).
-- PREČO: nový cvik alebo oprava = formulár v admin paneli (Katalóg cvikov),
-- nie commit do Configs/strength_catalog.py, strength_muscles.py a troch
-- FE súborov. Kód ostáva len ako záloha, keď DB nie je dostupná.
--
-- names      = {"sk","cs","en"} – názov v appke
-- data       = polia pre výber cvikov a AI (target, pattern, tier, equipment,
--              load_type, unilateral, measure, load_mode, skill_demand,
--              fatigue_cost, eccentric_load, rep_suitability, sport_tags,
--              contraindications, name_en) – rovnaký tvar ako v kóde
-- muscles    = {"quads": 1.0, "glutes": 0.5} – 1.0 hlavná, 0.5 pomocná partia
-- categories = plyo / iso (filter vo výbere, do objemu sa nerátajú)
-- active     = false skryje cvik z výberu, staré zápisy ho ďalej poznajú
--
-- Číta BE (service role, cache v pamäti) a FE cez BE (/strength-catalog).
-- Zápis len cez BE admin endpointy (service role) – RLS dovolí len čítanie.

create table if not exists public.strength_exercises (
  id          text primary key,
  names       jsonb not null default '{}'::jsonb,
  data        jsonb not null default '{}'::jsonb,
  muscles     jsonb not null default '{}'::jsonb,
  categories  text[] not null default '{}',
  active      boolean not null default true,
  sort_order  integer,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  updated_by  bigint
);

alter table public.strength_exercises enable row level security;

drop policy if exists strength_exercises_read on public.strength_exercises;
create policy strength_exercises_read on public.strength_exercises
  for select to authenticated using (true);

-- Návrhy cvikov od userov: ku ktorému cviku vedú, kedy ich admin vybavil a upozornil autora
alter table public.exercise_suggestions add column if not exists exercise_id text;
alter table public.exercise_suggestions add column if not exists reviewed_at timestamptz;
alter table public.exercise_suggestions add column if not exists notified_at timestamptz;
alter table public.exercise_suggestions add column if not exists admin_note text;

-- Seed z kódu (stav k migrácii). ON CONFLICT DO NOTHING – opakované
-- spustenie neprepíše úpravy z admin panelu.
on conflict (id) do nothing;
